-- Which Source a search by name asks first, per Kind (ADR-0011, superseding ADR-0006's single
-- order). Generated by `drizzle-kit generate` from `db/schema.ts`; the rows and the comments
-- at the end are by hand.
--
-- The order comes from the measurement in `docs/research/sources.md` (§7, §9g): Vivino found
-- 14 of 14 wines and Open Food Facts 2; on spirits Open Food Facts found more, with a barcode
-- and a strength, and Vivino's records are user-entered. Grappa and sake are the exceptions
-- among the rest — the only hits for them were Vivino's. Vermouth, beer, cider and mead were
-- not measured, and keep the default: routed like the spirits.
--
-- A column rather than a list in code, for the reason `has_vintages` is one (ADR-0002): a Kind
-- a copy's owner adds is routed by its own row, and starts with the open source.

ALTER TABLE "kinds" ADD COLUMN "first_source" text DEFAULT 'openfoodfacts' NOT NULL;--> statement-breakpoint
ALTER TABLE "kinds" ADD CONSTRAINT "kinds_first_source_is_known" CHECK ("kinds"."first_source" in ('openfoodfacts', 'vivino'));
--> statement-breakpoint
update kinds set first_source = 'vivino'
 where id in ('kind_red', 'kind_white', 'kind_rose', 'kind_orange', 'kind_sparkling',
              'kind_sweet', 'kind_fortified', 'kind_grappa', 'kind_sake');
--> statement-breakpoint
comment on column kinds.first_source is
  'The Source a search by name asks first for a Label of this Kind: vivino or openfoodfacts (ADR-0011). A barcode always goes to Open Food Facts.';
--> statement-breakpoint
comment on table label_sources is
  'An external catalogue a Label was found in: Open Food Facts or Vivino, asked in the order the Kind names (ADR-0011). Never the owner of the record.';
